fn numpy_insert<T>(mut arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    // Ensure idx is in [0, arr.len()]
    assert!(idx <= arr.len());

    // Vec::insert shifts all elements at positions >= idx to the right by one
    arr.insert(idx, value);

    arr
}

